    "Authority": {"Explanation": "The email does not claim or display authority through a recognized institution, title, or role. It simply references a website without establishing its credibility."},
    "Commitment/Consistency": {"Explanation": "The email does not reference prior behavior or choices to push for further action. There is no indication of past commitments or consistency."},
    "Liking": {"Explanation": "The email does not use familiarity, flattery, or personalization to build trust or rapport. It does not address the recipient by name or use any friendly language."},
    "Social proof": {"Explanation": "The email does not reference other people's participation or endorsement. It does not mention any testimonials or group support for the service."}
}

